  assert.equal(r2.value.lines[0].qty, 5);
});

test('addLine validates quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);

  assert.deepEqual(addLine(r.value, { sku: 'DEV-HOUR', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
  assert.deepEqual(addLine(r.value, { sku: 'DEV-HOUR', qty: -5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
  assert.deepEqual(addLine(r.value, { sku: 'DEV-HOUR', qty: 2.5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine validates SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);

  assert.deepEqual(addLine(r.value, { sku: 'NOPE', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine rejects non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 3, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('addLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);
  const original = r.value;
  const originalLength = original.lines.length;

  addLine(original, { sku: 'DEV-HOUR', qty: 2 });
  assert.equal(original.lines.length, originalLength);
});

test('removeLine removes a line by SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  });
