    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);

  assert.deepEqual(removeLine(r.value, 'NOPE'), {
    ok: false,
    error: 'LINE_NOT_FOUND',
  });
});

test('removeLine rejects if it would remove the last line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);

  assert.deepEqual(removeLine(r.value, 'DES-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
});

test('removeLine rejects non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', qty: 3, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', qty: 2, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 },
    ],
  };

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('removeLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  const original = r.value;
  const originalLength = original.lines.length;

  removeLine(original, 'DES-HOUR');
  assert.equal(original.lines.length, originalLength);
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);

  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0001');
  assert.equal(r2.value.status, 'issued');
  assert.equal(r2.value.customerId, 'C-001');
  assert.equal(r2.value.issueDate, '2026-10-07');
  assert.equal(r2.value.lines.length, 1);
});

test('issueInvoice uses existing numbers to avoid collisions', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);

  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const r2 = issueInvoice(r.value, existing);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0003');
});

test('issueInvoice rejects non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 3, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
