  assert.deepEqual(issueInvoice(invoice, []), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('issueInvoice preserves all invoice data', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);

  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.customerId, 'C-002');
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r2.value.lines[0].qty, 3);
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].qty, 5);
});

test('issueInvoice does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);
  const original = r.value;

  issueInvoice(original, []);
  assert.equal(original.status, 'draft');
  assert.equal(original.number, undefined);
});

